&lt;table CLASS=&quot;tablo centre autoalt&quot;&gt;&lt;caption&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;TABLESORTSCONNUSBARDE&quot; href=&quot;#TABLESORTSCONNUSBARDE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;Sorts connus par le barde&lt;/caption&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td ROWSPAN=&quot;2&quot;&gt;Niveau&lt;/td&gt;&lt;td COLSPAN=&quot;7&quot; CLASS=&quot;avecsoustitre&quot;&gt;Sorts connus&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;soustitre&quot;&gt;&lt;td&gt;0&lt;/td&gt;&lt;td&gt;1er&lt;/td&gt;&lt;td&gt;2e&lt;/td&gt;&lt;td&gt;3e&lt;/td&gt;&lt;td&gt;4e&lt;/td&gt;&lt;td&gt;5e&lt;/td&gt;&lt;td&gt;6e&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;1&lt;/td&gt;&lt;td&gt;4&lt;/td&gt;&lt;td&gt;2&lt;/td&gt;&lt;td&gt;-&lt;/td&gt;&lt;td&gt;-&lt;/td&gt;&lt;td&gt;-&lt;/td&gt;&lt;td&gt;-&lt;/td&gt;&lt;td&gt;-&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;2&lt;/td&gt;&lt;td&gt;5&lt;/td&gt;&lt;td&gt;3&lt;/td&gt;&lt;td&gt;-&lt;/td&gt;&lt;td&gt;-&lt;/td&gt;&lt;td&gt;-&lt;/td&gt;&lt;td&gt;-&lt;/td&gt;&lt;td&gt;-&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;3&lt;/td&gt;&lt;td&gt;6&lt;/td&gt;&lt;td&gt;4&lt;/td&gt;&lt;td&gt;-&lt;/td&gt;&lt;td&gt;-&lt;/td&gt;&lt;td&gt;-&lt;/td&gt;&lt;td&gt;-&lt;/td&gt;&lt;td&gt;-&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;4&lt;/td&gt;&lt;td&gt;6&lt;/td&gt;&lt;td&gt;4&lt;/td&gt;&lt;td&gt;2&lt;/td&gt;&lt;td&gt;-&lt;/td&gt;&lt;td&gt;-&lt;/td&gt;&lt;td&gt;-&lt;/td&gt;&lt;td&gt;-&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;5&lt;/td&gt;&lt;td&gt;6&lt;/td&gt;&lt;td&gt;4&lt;/td&gt;&lt;td&gt;3&lt;/td&gt;&lt;td&gt;-&lt;/td&gt;&lt;td&gt;-&lt;/td&gt;&lt;td&gt;-&lt;/td&gt;&lt;td&gt;-&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;6&lt;/td&gt;&lt;td&gt;6&lt;/td&gt;&lt;td&gt;4&lt;/td&gt;&lt;td&gt;4&lt;/td&gt;&lt;td&gt;-&lt;/td&gt;&lt;td&gt;-&lt;/td&gt;&lt;td&gt;-&lt;/td&gt;&lt;td&gt;-&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;7&lt;/td&gt;&lt;td&gt;6&lt;/td&gt;&lt;td&gt;5&lt;/td&gt;&lt;td&gt;4&lt;/td&gt;&lt;td&gt;2&lt;/td&gt;&lt;td&gt;-&lt;/td&gt;&lt;td&gt;-&lt;/td&gt;&lt;td&gt;-&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;8&lt;/td&gt;&lt;td&gt;6&lt;/td&gt;&lt;td&gt;5&lt;/td&gt;&lt;td&gt;4&lt;/td&gt;&lt;td&gt;3&lt;/td&gt;&lt;td&gt;-&lt;/td&gt;&lt;td&gt;-&lt;/td&gt;&lt;td&gt;-&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;9&lt;/td&gt;&lt;td&gt;6&lt;/td&gt;&lt;td&gt;5&lt;/td&gt;&lt;td&gt;4&lt;/td&gt;&lt;td&gt;4&lt;/td&gt;&lt;td&gt;-&lt;/td&gt;&lt;td&gt;-&lt;/td&gt;&lt;td&gt;-&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;10&lt;/td&gt;&lt;td&gt;6&lt;/td&gt;&lt;td&gt;5&lt;/td&gt;&lt;td&gt;5&lt;/td&gt;&lt;td&gt;4&lt;/td&gt;&lt;td&gt;2&lt;/td&gt;&lt;td&gt;-&lt;/td&gt;&lt;td&gt;-&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;11&lt;/td&gt;&lt;td&gt;6&lt;/td&gt;&lt;td&gt;6&lt;/td&gt;&lt;td&gt;5&lt;/td&gt;&lt;td&gt;4&lt;/td&gt;&lt;td&gt;3&lt;/td&gt;&lt;td&gt;-&lt;/td&gt;&lt;td&gt;-&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;12&lt;/td&gt;&lt;td&gt;6&lt;/td&gt;&lt;td&gt;6&lt;/td&gt;&lt;td&gt;5&lt;/td&gt;&lt;td&gt;4&lt;/td&gt;&lt;td&gt;4&lt;/td&gt;&lt;td&gt;-&lt;/td&gt;&lt;td&gt;-&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;13&lt;/td&gt;&lt;td&gt;6&lt;/td&gt;&lt;td&gt;6&lt;/td&gt;&lt;td&gt;5&lt;/td&gt;&lt;td&gt;5&lt;/td&gt;&lt;td&gt;4&lt;/td&gt;&lt;td&gt;2&lt;/td&gt;&lt;td&gt;-&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;14&lt;/td&gt;&lt;td&gt;6&lt;/td&gt;&lt;td&gt;6&lt;/td&gt;&lt;td&gt;6&lt;/td&gt;&lt;td&gt;5&lt;/td&gt;&lt;td&gt;4&lt;/td&gt;&lt;td&gt;3&lt;/td&gt;&lt;td&gt;-&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;15&lt;/td&gt;&lt;td&gt;6&lt;/td&gt;&lt;td&gt;6&lt;/td&gt;&lt;td&gt;6&lt;/td&gt;&lt;td&gt;5&lt;/td&gt;&lt;td&gt;4&lt;/td&gt;&lt;td&gt;4&lt;/td&gt;&lt;td&gt;-&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;16&lt;/td&gt;&lt;td&gt;6&lt;/td&gt;&lt;td&gt;6&lt;/td&gt;&lt;td&gt;6&lt;/td&gt;&lt;td&gt;5&lt;/td&gt;&lt;td&gt;5&lt;/td&gt;&lt;td&gt;4&lt;/td&gt;&lt;td&gt;2&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;17&lt;/td&gt;&lt;td&gt;6&lt;/td&gt;&lt;td&gt;6&lt;/td&gt;&lt;td&gt;6&lt;/td&gt;&lt;td&gt;6&lt;/td&gt;&lt;td&gt;5&lt;/td&gt;&lt;td&gt;4&lt;/td&gt;&lt;td&gt;3&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;18&lt;/td&gt;&lt;td&gt;6&lt;/td&gt;&lt;td&gt;6&lt;/td&gt;&lt;td&gt;6&lt;/td&gt;&lt;td&gt;6&lt;/td&gt;&lt;td&gt;5&lt;/td&gt;&lt;td&gt;4&lt;/td&gt;&lt;td&gt;4&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;19&lt;/td&gt;&lt;td&gt;6&lt;/td&gt;&lt;td&gt;6&lt;/td&gt;&lt;td&gt;6&lt;/td&gt;&lt;td&gt;6&lt;/td&gt;&lt;td&gt;5&lt;/td&gt;&lt;td&gt;5&lt;/td&gt;&lt;td&gt;4&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;20&lt;/td&gt;&lt;td&gt;6&lt;/td&gt;&lt;td&gt;6&lt;/td&gt;&lt;td&gt;6&lt;/td&gt;&lt;td&gt;6&lt;/td&gt;&lt;td&gt;6&lt;/td&gt;&lt;td&gt;5&lt;/td&gt;&lt;td&gt;5&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
&lt;/div&gt;&lt;/div&gt;&lt;b&gt;R&#244;le.&lt;/b&gt; Les bardes excellent dans l’art de troubler et de d&#233;stabiliser leurs ennemis tout en encourageant leurs amis &#224; toujours se d&#233;passer. Ils savent manier &#224; la fois les armes et la magie, mais leur v&#233;ritable force r&#233;side en-dehors de la m&#234;l&#233;e, o&#249; ils peuvent aider leurs compagnons et nuire &#224; leurs ennemis sans craindre de voir leurs performances interrompues.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Alignement.&lt;/b&gt; Au choix.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;D&#233;s de vie.&lt;/b&gt; d8.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Argent de d&#233;part.&lt;/b&gt; 3d6 x 10 po (moyenne 105 po).&lt;br /&gt;&lt;br /&gt;&lt;h2 class=&quot;separator&quot;&gt;Comp&#233;tences de classe&lt;a class=&quot;headeranchor&quot; id=&quot;Comp&#233;tences_de_classe_9&quot; href=&quot;#Comp&#233;tences_de_classe_9&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;Les comp&#233;tences de classe du barde sont les suivantes : &lt;a class=&quot;pagelink&quot; href=&quot;Acrobaties.html&quot; title=&quot;Acrobaties&quot;&gt;Acrobaties&lt;/a&gt; (Dex), &lt;a class=&quot;pagelink&quot; href=&quot;Art-De-La-Magie.html&quot; title=&quot;Art de la magie&quot;&gt;Art de la magie&lt;/a&gt; (Int), &lt;a class=&quot;pagelink&quot; href=&quot;Artisanat.html&quot; title=&quot;Artisanat&quot;&gt;Artisanat&lt;/a&gt; (Int), &lt;a class=&quot;pagelink&quot; href=&quot;Bluff.html&quot; title=&quot;Bluff&quot;&gt;Bluff&lt;/a&gt; (Cha), &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (tous les domaines) (Int), &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;guisement.html&quot; title=&quot;D&#233;guisement&quot;&gt;D&#233;guisement&lt;/a&gt; (Cha), &lt;a class=&quot;pagelink&quot; href=&quot;Diplomatie.html&quot; title=&quot;Diplomatie&quot;&gt;Diplomatie&lt;/a&gt; (Cha), &lt;a class=&quot;pagelink&quot; href=&quot;Discr&#233;tion.html&quot; title=&quot;Discr&#233;tion&quot;&gt;Discr&#233;tion&lt;/a&gt; (Dex), &lt;a class=&quot;pagelink&quot; href=&quot;Escalade.html&quot; title=&quot;Escalade&quot;&gt;Escalade&lt;/a&gt; (For), &lt;a class=&quot;pagelink&quot; href=&quot;Escamotage.html&quot; title=&quot;Escamotage&quot;&gt;Escamotage&lt;/a&gt; (Dex), &lt;a class=&quot;pagelink&quot; href=&quot;Estimation.html&quot; title=&quot;Estimation&quot;&gt;Estimation&lt;/a&gt; (Int), &lt;a class=&quot;pagelink&quot; href=&quot;&#201;vasion.html&quot; title=&quot;&#201;vasion&quot;&gt;&#201;vasion&lt;/a&gt; (Dex), &lt;a class=&quot;pagelink&quot; href=&quot;Intimidation.html&quot; title=&quot;Intimidation&quot;&gt;Intimidation&lt;/a&gt; (Cha), &lt;a class=&quot;pagelink&quot; href=&quot;Linguistique.html&quot; title=&quot;Linguistique&quot;&gt;Linguistique&lt;/a&gt; (Int), &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; (Sag), &lt;a class=&quot;pagelink&quot; href=&quot;Profession.html&quot; title=&quot;Profession&quot;&gt;Profession&lt;/a&gt; (Sag), &lt;a class=&quot;pagelink&quot; href=&quot;Psychologie.html&quot; title=&quot;Psychologie&quot;&gt;Psychologie&lt;/a&gt; (Sag), &lt;a class=&quot;pagelink&quot; href=&quot;Repr&#233;sentation.html&quot; title=&quot;Repr&#233;sentation&quot;&gt;Repr&#233;sentation&lt;/a&gt; (Cha) et &lt;a class=&quot;pagelink&quot; href=&quot;Utilisation-Dobjets-Magiques.html&quot; title=&quot;Utilisation d&amp;#39;objets magiques&quot;&gt;Utilisation d’objets magiques&lt;/a&gt; (Cha).&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Points de comp&#233;tence par niveau.&lt;/b&gt; 6 + modificateur d’&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Intelligence.html&quot; title=&quot;L&amp;#39;Intelligence&quot;&gt;Intelligence&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h2 class=&quot;separator&quot;&gt;Descriptif de la classe&lt;a class=&quot;headeranchor&quot; id=&quot;Descriptif_de_la_classe_10&quot; href=&quot;#Descriptif_de_la_classe_10&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;Les aptitudes du barde sont d&#233;crites ci-dessous.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Armes et armures&lt;a class=&quot;headeranchor&quot; id=&quot;Armes_et_armures_0&quot; href=&quot;#Armes_et_armures_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Le barde est form&#233; au maniement de toutes les &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armes#Armecourante.html&quot; title=&quot;arme courante&quot;&gt;armes courantes&lt;/a&gt; ainsi que de l’arc court, l’&#233;p&#233;e courte, l’&#233;p&#233;e longue, la matraque, la rapi&#232;re, et du fouet. Il est &#233;galement form&#233; au port des &lt;a class=&quot;pagelink&quot; href=&quot;Tableau-R&#233;capitulatif-Des-Armures#Legeres.html&quot; title=&quot;armure l&#233;g&#232;re&quot;&gt;armures l&#233;g&#232;res&lt;/a&gt; et &#224; l’utilisation des boucliers (&#224; l’exception des pavois). Il peut porter une &lt;a class=&quot;pagelink&quot; href=&quot;Tableau-R&#233;capitulatif-Des-Armures#Legeres.html&quot; title=&quot;armure l&#233;g&#232;re&quot;&gt;armure l&#233;g&#232;re&lt;/a&gt; et utiliser un bouclier sans encourir de risque d’&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armures#Risqueechecprofane.html&quot; title=&quot;&#233;chec des sorts&quot;&gt;&#233;chec des sorts&lt;/a&gt;. S’il porte une &lt;a class=&quot;pagelink&quot; href=&quot;Tableau-R&#233;capitulatif-Des-Armures#Intermediaires.html&quot; title=&quot;armure interm&#233;diaire&quot;&gt;armure interm&#233;diaire&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;Tableau-R&#233;capitulatif-Des-Armures#Lourdes.html&quot; title=&quot;armure lourde&quot;&gt;lourde&lt;/a&gt;, le risque d’&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armures#Risqueechecprofane.html&quot; title=&quot;&#233;chec des sorts&quot;&gt;&#233;chec des sorts&lt;/a&gt; s’applique normalement lorsque le sort lanc&#233; poss&#232;de une composante gestuelle (comme pour les autres lanceurs de sorts profanes). Ces particularit&#233;s ne concernent que les sorts de barde : les r&#232;gles normales s’appliquent dans le cas des sorts qu’un barde &lt;a class=&quot;pagelink&quot; href=&quot;Progression-Des-Personnages#Multiclasser.html&quot; title=&quot;multiclass&#233;&quot;&gt;multiclass&#233;&lt;/a&gt; re&#231;oit gr&#226;ce &#224; d’autres classes.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Sorts&lt;a class=&quot;headeranchor&quot; id=&quot;Sorts_1&quot; href=&quot;#Sorts_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Un barde peut lancer des sorts profanes appartenant &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Liste-Des-Sorts-De-Bardes.html&quot; title=&quot;Liste des sorts de barde&quot;&gt;liste des sorts de bardes&lt;/a&gt;. Il peut lancer les sorts qu’il conna&#238;t sans devoir les pr&#233;parer &#224; l’avance. Tous les sorts qu’un barde lance s’accompagnent d’une composante verbale (qui peut prendre la forme d’une chanson, d’un po&#232;me ou d’un air de musique). Pour apprendre ou lancer un sort, le barde doit avoir une valeur de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Charisme.html&quot; title=&quot;Le Charisme&quot;&gt;Charisme&lt;/a&gt; d’au moins 10 + le niveau du sort. Le &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;degr&#233; de difficult&#233;&lt;/a&gt; des &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;jet de sauvegarde&quot;&gt;jets de sauvegarde&lt;/a&gt; contre ses sorts vaut 10 + le &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Niveau.html&quot; title=&quot;Niveau de sort&quot;&gt;niveau du sort&lt;/a&gt; + le modificateur de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Charisme.html&quot; title=&quot;Le Charisme&quot;&gt;Charisme&lt;/a&gt; du barde.&lt;br /&gt;&lt;br /&gt;Comme les autres lanceurs de sorts, le barde ne peut lancer qu’un certain nombre de sorts de chaque niveau chaque jour. Son quota de sorts quotidiens est indiqu&#233; sur la Table &quot;&lt;a class=&quot;pagelink&quot; href=&quot;Barde.html#TABLEBARDE&quot; title=&quot;Le barde&quot;&gt;Le Barde&lt;/a&gt;&quot;. En plus de cela, il re&#231;oit des sorts en bonus chaque jour s’il poss&#232;de un &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Charisme.html&quot; title=&quot;Le Charisme&quot;&gt;Charisme&lt;/a&gt; &#233;lev&#233; (voir la Table &quot;&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques.html#TABLEAUCARACTERISTIQUES&quot; title=&quot;Les caract&#233;ristiques&quot;&gt;Modificateurs de caract&#233;ristique et sorts en bonus&lt;/a&gt;&quot;).&lt;br /&gt;&lt;br /&gt;Le barde poss&#232;de un r&#233;pertoire de sorts tr&#232;s limit&#233;. Il commence sa carri&#232;re en connaissant seulement quatre sorts du niveau 0 et deux sorts du 1&lt;sup&gt;er&lt;/sup&gt; niveau (il peut choisir ces sorts). Chaque fois qu’il gagne un niveau de barde, il re&#231;oit un ou plusieurs nouveaux sorts, comme indiqu&#233; sur la Table &quot;&lt;a class=&quot;pagelink&quot; href=&quot;Barde.html#TABLESORTSCONNUSBARDE&quot; title=&quot;Le barde&quot;&gt;Sorts connus par le barde&lt;/a&gt;&quot; (contrairement au quota de sorts quotidiens, le nombre de sorts connus par un barde n’est pas modifi&#233; par sa valeur de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Charisme.html&quot; title=&quot;Le Charisme&quot;&gt;Charisme&lt;/a&gt; ; les chiffres de la Table &quot;&lt;a class=&quot;pagelink&quot; href=&quot;Barde.html#TABLESORTSCONNUSBARDE&quot; title=&quot;Le barde&quot;&gt;Sorts connus par le barde&lt;/a&gt;&quot; sont fixes).&lt;br /&gt;&lt;br /&gt;Lorsqu’il atteint le niveau 5, et tous les trois niveaux de barde suivants (aux niveaux 8, 11, etc.), le barde peut choisir d’apprendre un nouveau sort &#224; la place de l’un de ceux qu’il conna&#238;t d&#233;j&#224;. Le barde oublie alors un sort au profit d’un autre. Le niveau du nouveau sort doit &#234;tre identique &#224; celui du sort oubli&#233;, et il ne peut s’agir d’un sort appartenant au plus haut niveau de sorts accessible au barde. Un barde ne peut &#233;changer qu’un seul sort &#224; chaque fois, et doit choisir s’il proc&#232;de &#224; un &#233;change au moment o&#249; il apprend de nouveaux sorts lors du passage de niveau.&lt;br /&gt;&lt;br /&gt;Un barde n’a pas besoin de pr&#233;parer ses sorts &#224; l’avance. Il peut lancer n’importe quel sort de son r&#233;pertoire &#224; n’importe quel moment, pour autant qu’il n’ait pas &#233;puis&#233; son quota de sorts de ce niveau pour la journ&#233;e.&lt;br /&gt;&lt;br /&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;SAVOIRBARDIQUE&quot; href=&quot;#SAVOIRBARDIQUE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Savoir bardique (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Savoir_bardique_Ext_2&quot; href=&quot;#Savoir_bardique_Ext_2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Un barde ajoute la moiti&#233; de son niveau de classe (au minimum 1) &#224; tous ses tests de &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; et peut utiliser n’importe quelle comp&#233;tence de &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt;, m&#234;me s’il n’a pas investi de points de comp&#233;tence dans celle-ci.&lt;br /&gt;&lt;br /&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;REPRESENTATIONBARDIQUE&quot; href=&quot;#REPRESENTATIONBARDIQUE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Repr&#233;sentation bardique&lt;a class=&quot;headeranchor&quot; id=&quot;Repr&#233;sentation_bardique_3&quot; href=&quot;#Repr&#233;sentation_bardique_3&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;&lt;IMG SRC=&quot;/wiki/public/upload/Illustrations/PNJ/Lem.jpg&quot; WIDTH=&quot;35%&quot; STYLE=&quot;float: right; background-color: white; padding: 0 0 5px 5px;&quot;/&gt;
Un barde peut utiliser la comp&#233;tence &lt;a class=&quot;pagelink&quot; href=&quot;Repr&#233;sentation.html&quot; title=&quot;Repr&#233;sentation&quot;&gt;Repr&#233;sentation&lt;/a&gt; pour cr&#233;er des effets magiques affectant ceux qui sont proches de lui, y compris lui-m&#234;me s’il le d&#233;sire. Chaque jour, il peut utiliser cette capacit&#233; pendant un nombre de rounds &#233;gal &#224; 4 + son modificateur de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Charisme.html&quot; title=&quot;Le Charisme&quot;&gt;Charisme&lt;/a&gt;. Ce nombre augmente de +2 &#224; chaque niveau de barde apr&#232;s le premier. Au fil des niveaux, le barde apprend &#224; produire diff&#233;rents effets. Chaque round, il peut choisir celui qu’il d&#233;sire utiliser.&lt;br /&gt;&lt;br /&gt;Il faut utiliser une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt; pour activer un effet de repr&#233;sentation bardique mais, pour maintenir en place un effet d&#233;j&#224; activ&#233; un round de plus, une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Libre.html&quot; title=&quot;Action libre&quot;&gt;action libre&lt;/a&gt; suffit. Pour passer &#224; un autre effet, le barde doit arr&#234;ter le pr&#233;c&#233;dent et utiliser une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt; pour activer le nouvel effet. Un adversaire ne peut interrompre une repr&#233;sentation bardique mais l’effet se termine imm&#233;diatement si le barde est tu&#233;, &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Paralys&#233;.html&quot; title=&quot;Paralys&#233;&quot;&gt;paralys&#233;&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#&#201;tourdi.html&quot; title=&quot;&#201;tourdi&quot;&gt;&#233;tourdi&lt;/a&gt;, s’il tombe &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Inconscient.html&quot; title=&quot;Inconscient&quot;&gt;inconscient&lt;/a&gt; ou s’il lui est impossible, pour une raison ou pour une autre, de d&#233;vouer une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Libre.html&quot; title=&quot;Action libre&quot;&gt;action libre&lt;/a&gt; chaque round pour le maintenir. Un barde ne peut appliquer qu’un seul effet de repr&#233;sentation bardique &#224; la fois.&lt;br /&gt;&lt;br /&gt;&#192; partir du niveau 7, le barde n’a besoin que d’une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Mouvement.html&quot; title=&quot;Action de mouvement&quot;&gt;action de mouvement&lt;/a&gt; pour activer un effet de repr&#233;sentation bardique. &#192; partir du niveau 13, une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Rapide.html&quot; title=&quot;Action rapide&quot;&gt;action rapide&lt;/a&gt; suffit.&lt;br /&gt;&lt;br /&gt;Chaque repr&#233;sentation bardique poss&#232;de une composante sonore, une composante visuelle, ou les deux.&lt;br /&gt;&lt;br /&gt;Dans le cas de composantes sonores, les cibles doivent &#234;tre capables d’entendre le barde et, dans la plupart des cas (voir les descriptions individuelles pour plus de pr&#233;cision) de comprendre le langage utilis&#233; pour &#234;tre affect&#233;es par la repr&#233;sentation. Un barde &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Assourdi.html&quot; title=&quot;Assourdi&quot;&gt;sourd&lt;/a&gt; a 20% de chances d’&#233;chec lorsqu’il entreprend une repr&#233;sentation &#224; composante sonore. En cas d’&#233;chec, la tentative est quand m&#234;me d&#233;compt&#233;e de son quota journalier. Les cr&#233;atures &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Assourdi.html&quot; title=&quot;Assourdi&quot;&gt;sourdes&lt;/a&gt; ne peuvent pas &#234;tre affect&#233;es par une repr&#233;sentation bardique &#224; composante sonore.&lt;br /&gt;&lt;br /&gt;Dans le cas de composantes visuelles, les cibles doivent disposer d’une ligne de mire jusqu’au barde pour &#234;tre affect&#233;es par sa repr&#233;sentation. Un barde &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Aveugl&#233;.html&quot; title=&quot;Aveugl&#233;&quot;&gt;aveugle&lt;/a&gt; a 50% de chances d’&#233;chec lorsqu’il entreprend une repr&#233;sentation &#224; composante visuelle. En cas d’&#233;chec, la tentative est quand m&#234;me d&#233;compt&#233;e de son quota journalier. Les cr&#233;atures &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Aveugl&#233;.html&quot; title=&quot;Aveugl&#233;&quot;&gt;aveugles&lt;/a&gt; ne peuvent pas &#234;tre affect&#233;es par une repr&#233;sentation bardique &#224; composante visuelle.&lt;br /&gt;&lt;br /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.LArt de la magie (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Magic/Art de la Magie&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUM.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;b&gt;Les chefs d&#39;œuvre.&lt;/b&gt; Les bardes apportent des nouvelles du vaste monde, divertissent les rois, servent de diplomates culturels et transmettent une riche tradition orale aux gens du peuple comme aux nobles. Certains les appellent les touche-&#224;-tout et disent qu’ils sont incapables de se sp&#233;cialiser, mais c’est faux. Ils sont les sp&#233;cialistes des histoires et les gardiens des l&#233;gendes, vers&#233;s dans les mythologies du monde entier. Leurs connaissances leur conf&#232;rent des pouvoirs mais leur puissance vient surtout de leur compr&#233;hension des subtilit&#233;s de l’art : qu’il s’agisse de musique, de trag&#233;die ou de com&#233;die, les bardes comprennent le pouvoir et l’attrait des histoires, des chants et des danses. Ils puisent dans ce savoir pour g&#233;n&#233;rer des pouvoirs surnaturels qui contribueront &#224; &#233;crire leur propre l&#233;gende.&lt;br /&gt;&lt;br /&gt;Cette partie pr&#233;sente les &lt;a class=&quot;pagelink&quot; href=&quot;Chefs-Doeuvre.html&quot; title=&quot;Les chefs d&amp;#39;œuvre du barde&quot;&gt;chefs-d&#39;œuvre&lt;/a&gt;, une version sp&#233;cialis&#233;e de la repr&#233;sentation bardique qui permet au barde de r&#233;aliser des exploits incroyables.&lt;br /&gt;&lt;br /&gt;&lt;i&gt;Voir la &lt;a class=&quot;pagelink&quot; href=&quot;Repr&#233;sentations.html&quot; title=&quot;Les repr&#233;sentations bardiques du barde&quot;&gt;liste des repr&#233;sentations bardiques&lt;/a&gt;.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;TOURSDEMAGIE&quot; href=&quot;#TOURSDEMAGIE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Tours de magie&lt;a class=&quot;headeranchor&quot; id=&quot;Tours_de_magie_4&quot; href=&quot;#Tours_de_magie_4&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Les bardes apprennent un certain nombre de tours de magie (ou sorts de niveau 0) comme indiqu&#233; dans la Table &quot;&lt;a class=&quot;pagelink&quot; href=&quot;Barde.html#TABLESORTSCONNUSBARDE&quot; title=&quot;Le barde&quot;&gt;Sorts connus par le barde&lt;/a&gt;&quot;. Ces sorts sont lanc&#233;s de la m&#234;me mani&#232;re que les autres mais ils ne n&#233;cessitent aucun &lt;a class=&quot;pagelink&quot; href=&quot;Emplacement-De-Sort.html&quot; title=&quot;emplacement de sort&quot;&gt;emplacement de sorts&lt;/a&gt; et peuvent &#234;tre utilis&#233;s de mani&#232;re illimit&#233;e.&lt;br /&gt;&lt;br /&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;VERSATILITEARTISTIQUE&quot; href=&quot;#VERSATILITEARTISTIQUE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Versatilit&#233; artistique (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Versatilit&#233;_artistique_Ext_5&quot; href=&quot;#Versatilit&#233;_artistique_Ext_5&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 2, un barde peut choisir une forme de la comp&#233;tence &lt;a class=&quot;pagelink&quot; href=&quot;Repr&#233;sentation.html&quot; title=&quot;Repr&#233;sentation&quot;&gt;Repr&#233;sentation&lt;/a&gt; et utiliser le modificateur correspondant &#224; la place des modificateurs de certaines comp&#233;tences auxquelles elles sont associ&#233;es. Lorsque le barde choisit de faire cette substitution, il utilise son bonus total pour la comp&#233;tence de &lt;a class=&quot;pagelink&quot; href=&quot;Repr&#233;sentation.html&quot; title=&quot;Repr&#233;sentation&quot;&gt;Repr&#233;sentation&lt;/a&gt; (y compris son bonus de &lt;a class=&quot;pagelink&quot; href=&quot;Tableau-R&#233;capitulatif-Des-Comp&#233;tences.html&quot; title=&quot;Tableau r&#233;capitulatif des comp&#233;tences&quot;&gt;comp&#233;tence de classe&lt;/a&gt;) au lieu de son bonus dans la comp&#233;tence associ&#233;e et ce, qu’il ait investi des points de comp&#233;tence dans celle-ci ou non. Au niveau 6 et tous les quatre niveaux par la suite, le barde peut choisir une nouvelle forme de la comp&#233;tence Repr&#233;sentation qu’il pourra &#233;galement utiliser pour cette substitution.&lt;br /&gt;&lt;br /&gt;Les formes de Repr&#233;sentation et leurs comp&#233;tences associ&#233;es sont : chant (&lt;a class=&quot;pagelink&quot; href=&quot;Bluff.html&quot; title=&quot;Bluff&quot;&gt;Bluff&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Psychologie.html&quot; title=&quot;Psychologie&quot;&gt;Psychologie&lt;/a&gt;), danse (&lt;a class=&quot;pagelink&quot; href=&quot;Acrobaties.html&quot; title=&quot;Acrobaties&quot;&gt;Acrobaties&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Vol.html&quot; title=&quot;Vol&quot;&gt;Vol&lt;/a&gt;), d&#233;clamation (&lt;a class=&quot;pagelink&quot; href=&quot;Diplomatie.html&quot; title=&quot;Diplomatie&quot;&gt;Diplomatie&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Psychologie.html&quot; title=&quot;Psychologie&quot;&gt;Psychologie&lt;/a&gt;), farce (&lt;a class=&quot;pagelink&quot; href=&quot;Bluff.html&quot; title=&quot;Bluff&quot;&gt;Bluff&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Intimidation.html&quot; title=&quot;Intimidation&quot;&gt;Intimidation&lt;/a&gt;), instruments &#224; clavier (&lt;a class=&quot;pagelink&quot; href=&quot;Diplomatie.html&quot; title=&quot;Diplomatie&quot;&gt;Diplomatie&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Intimidation.html&quot; title=&quot;Intimidation&quot;&gt;Intimidation&lt;/a&gt;), instruments &#224; cordes (&lt;a class=&quot;pagelink&quot; href=&quot;Bluff.html&quot; title=&quot;Bluff&quot;&gt;Bluff&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Diplomatie.html&quot; title=&quot;Diplomatie&quot;&gt;Diplomatie&lt;/a&gt;), instruments &#224; vent (&lt;a class=&quot;pagelink&quot; href=&quot;Diplomatie.html&quot; title=&quot;Diplomatie&quot;&gt;Diplomatie&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Dressage.html&quot; title=&quot;Dressage&quot;&gt;Dressage&lt;/a&gt;), percussions (&lt;a class=&quot;pagelink&quot; href=&quot;Dressage.html&quot; title=&quot;Dressage&quot;&gt;Dressage&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Intimidation.html&quot; title=&quot;Intimidation&quot;&gt;Intimidation&lt;/a&gt;) et sc&#232;ne (&lt;a class=&quot;pagelink&quot; href=&quot;Bluff.html&quot; title=&quot;Bluff&quot;&gt;Bluff&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;guisement.html&quot; title=&quot;D&#233;guisement&quot;&gt;D&#233;guisement&lt;/a&gt;).&lt;br /&gt;&lt;br /&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;ERUDITION&quot; href=&quot;#ERUDITION&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;&#201;rudition (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;&#201;rudition_Ext_6&quot; href=&quot;#&#201;rudition_Ext_6&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 2, le barde acquiert une certaine r&#233;sistance aux repr&#233;sentations des autres bardes et aux effets de son en g&#233;n&#233;ral. Il gagne un bonus de +4 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;jet de sauvegarde&quot;&gt;jets de sauvegarde&lt;/a&gt; contre les effets des repr&#233;sentations bardiques, les effets de son et les effets de langage.&lt;br /&gt;&lt;br /&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;MAITREDUSAVOIR&quot; href=&quot;#MAITREDUSAVOIR&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Ma&#238;tre du savoir (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Ma&#238;tre_du_savoir_Ext_7&quot; href=&quot;#Ma&#238;tre_du_savoir_Ext_7&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;&lt;div style=&quot;float:right; padding-left: 6px&quot;&gt;
&lt;table&gt;
&lt;tr style=&quot;vertical-align:bottom&quot;&gt;
&lt;td style=&quot;display:none; background-color: #f3efe2; border: 1px solid #4b3124; padding: 2px; text-align: left&quot;&gt;
&lt;table&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;&lt;td&gt;
&lt;b&gt;&lt;i&gt;&lt;u&gt;Ce texte a &#233;t&#233; modifi&#233; suite &#224; la FAQ suivante :&lt;/u&gt;&lt;br /&gt;&lt;br /&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Faq--Manuel-Des-Joueurs-(Races-Et-Classes).html#4&quot; title=&quot;FAQ du Manuel des joueurs, section races et classes&quot;&gt;→&lt;/a&gt; Capacit&#233; de barde ma&#238;tre du savoir et faire 10 : Puis-je faire 10 sur les tests de Connaissances ? La comp&#233;tence Connaissances ne dit pas que c’est impossible, mais si c’est vrai, la premi&#232;re moiti&#233; de la capacit&#233; de barde ma&#238;tre du savoir ne fait rien.&lt;/i&gt;&lt;/b&gt;&lt;br /&gt;&lt;br /&gt;Oui, c’est possible. La capacit&#233; de barde &lt;u&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Barde.html#MAITREDUSAVOIR&quot; title=&quot;Le barde&quot;&gt;ma&#238;tre du savoir&lt;/a&gt;&lt;/u&gt; devrait pr&#233;ciser &#224; la fin de cette premi&#232;re phrase &#171; , et ce m&#234;me lorsqu&#39;il est distrait ou menac&#233; &#187;.
&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/td&gt;
&lt;td&gt;&lt;img style=&quot;width:50px; cursor:pointer&quot; src=&quot;/wiki/public/upload/Illustrations/Wiki/faqbase1.png&quot; title=&quot;Cliquez pour afficher/cacher une FAQ officielle relative &#224; ce texte&quot; alt=&quot;Cliquez pour afficher/cacher l&#39;information&quot; onclick=&quot;
var cible = this.parentNode.previousSibling.previousSibling;
if (cible.style.display==&#39;none&#39;) {
  $(cible).show(&#39;slide&#39;);
  $(this).fadeTo(500,0.4);
} else {
  $(cible).hide(&#39;slide&#39;);
  $(this).fadeTo(500,1);
}&quot; ONMOUSEOVER=&quot;this.src = &#39;/wiki/public/upload/Illustrations/Wiki/faqalt1.png&#39;;&quot;
ONMOUSEOUT=&quot;this.src = &#39;/wiki/public/upload/Illustrations/Wiki/faqbase1.png&#39;;&quot; /&gt;
&lt;/td&gt;
&lt;/tr&gt;
&lt;/table&gt;
&lt;/div&gt;Au niveau 5, le barde devient un ma&#238;tre &#233;rudit et peut &#171; &lt;a class=&quot;pagelink&quot; href=&quot;Comp&#233;tences.html#FAIRE10&quot; title=&quot;Les comp&#233;tences&quot;&gt;faire 10&lt;/a&gt; &#187; chaque fois qu’il doit r&#233;aliser un &lt;a class=&quot;pagelink&quot; href=&quot;Comp&#233;tences#Testsdecompetences.html&quot; title=&quot;test de comp&#233;tence&quot;&gt;test de comp&#233;tence&lt;/a&gt; relatif &#224; une cat&#233;gorie de &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; dans laquelle il a investi des points de comp&#233;tence, et ce m&#234;me lorsqu&#39;il est distrait ou menac&#233;. Le barde n’est pas oblig&#233; de &#171; &lt;a class=&quot;pagelink&quot; href=&quot;Comp&#233;tences.html#FAIRE10&quot; title=&quot;Les comp&#233;tences&quot;&gt;faire 10&lt;/a&gt; &#187; et peut choisir de lancer le d&#233; normalement. De plus, une fois par jour, le barde peut &#171; &lt;a class=&quot;pagelink&quot; href=&quot;Comp&#233;tences.html#FAIRE10&quot; title=&quot;Les comp&#233;tences&quot;&gt;faire 20&lt;/a&gt; &#187; sur un test de &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; en utilisant une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;. Tous les six niveaux de barde apr&#232;s le niveau 5, il peut utiliser cette capacit&#233; une fois de plus chaque jour, jusqu’&#224; un maximum de trois utilisations quotidiennes au niveau 17.&lt;br /&gt;&lt;br /&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;TOUCHE-A-TOUT&quot; href=&quot;#TOUCHE-A-TOUT&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Touche-&#224;-tout (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Touche-&#224;-tout_Ext_8&quot; href=&quot;#Touche-&#224;-tout_Ext_8&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 10, le barde peut utiliser n’importe quelle &lt;a class=&quot;pagelink&quot; href=&quot;Tableau-R&#233;capitulatif-Des-Comp&#233;tences.html&quot; title=&quot;Tableau r&#233;capitulatif des comp&#233;tences&quot;&gt;comp&#233;tence&lt;/a&gt;, m&#234;me celles qui ne peuvent normalement pas &#234;tre utilis&#233;es sans formation. Au niveau 16, toutes les &lt;a class=&quot;pagelink&quot; href=&quot;Tableau-R&#233;capitulatif-Des-Comp&#233;tences.html&quot; title=&quot;Tableau r&#233;capitulatif des comp&#233;tences&quot;&gt;comp&#233;tences&lt;/a&gt; sont des comp&#233;tences de classe pour le barde. Au niveau 19, le barde peut choisir de &#171; &lt;a class=&quot;pagelink&quot; href=&quot;Comp&#233;tences.html#FAIRE10&quot; title=&quot;Les comp&#233;tences&quot;&gt;faire 10&lt;/a&gt; &#187; chaque fois qu’il doit r&#233;aliser un &lt;a class=&quot;pagelink&quot; href=&quot;Comp&#233;tences#Testsdecompetences.html&quot; title=&quot;test de comp&#233;tence&quot;&gt;test de comp&#233;tence&lt;/a&gt; et ce quelle que soit la &lt;a class=&quot;pagelink&quot; href=&quot;Tableau-R&#233;capitulatif-Des-Comp&#233;tences.html&quot; title=&quot;Tableau r&#233;capitulatif des comp&#233;tences&quot;&gt;comp&#233;tence&lt;/a&gt;, m&#234;me s’il s’agit d’une &lt;a class=&quot;pagelink&quot; href=&quot;Tableau-R&#233;capitulatif-Des-Comp&#233;tences.html&quot; title=&quot;Tableau r&#233;capitulatif des comp&#233;tences&quot;&gt;comp&#233;tence&lt;/a&gt; qui n’autorise normalement pas cette possibilit&#233;.
